# Core asset pipeline (was plugins/web_common/Hammerfile).
#
#   lux assets:auto    - run *.ext.rb generators, build auto-*.tmp.{js,scss}
#   lux assets:build   - bun run rollup -c
#   lux assets:upload  - fingerprint + CDN
#   lux assets:deploy  - auto -> build -> upload
#
# Generators: `name.ext.rb` under app/assets/auto/<folder>/{js,css}/ is
# evaluated; last returned string is written to `name.tmp.ext` with an
# autogenerated banner (gitignored via *.tmp.*).

module LuxAssets
  module_function

  def auto_assets
    # An app with no JS build (no web_common mount, no hand-written packs) has
    # no auto/ tree at all; `lux s` runs this unconditionally, so do nothing.
    return unless Dir.exist?('./app/assets/auto')

    system 'rm -f ./app/assets/auto-*'

    for folder in Dir.folders('./app/assets/auto')
      info = ["Auto asset compiler: #{folder}"]

      run_generators! folder, :js
      run_generators! folder, :css

      js_files = get_files folder, :js
      data = []
      for file in js_files
        if file.start_with?('/* ') || file.start_with?('// ')
          data.push file
        else
          ext = file.split('.').last.to_sym
          if ext == :svelte
            name = file.split('/').last.split('.').first.gsub('-', '_')
            data.push <<~DATA
              import Svelte_#{name} from '#{file}';
              Svelte.bind('s-#{name.gsub('_', '-')}', Svelte_#{name});
            DATA
              .chomp
          elsif [:js, :coffee, :fez].include?(ext)
            data.push %[import "#{file}";]
          else
            raise "Unknown extension on #{file}"
          end
        end
      end

      if data[0]
        file = "./app/assets/auto-#{folder}.tmp.js"
        info.push file
        File.write(file, data.join("\n\n"))
      end

      css_files = get_files folder, :css
      data = []
      for file in css_files
        if file.start_with?('/* ')
          data.push file
        else
          # plain @import (not meta.load-css) so `sass --watch` tracks these
          # partials as deps and rebuilds on edit; load-css targets aren't watched
          data.push %[  @import "#{file}";]
        end
      end

      if data[0]
        css = <<~DATA
          /* DO NOT EDIT - auto generated by assets:auto - edit source at ./app/assets/auto/#{folder}/css */

          @layer base {
          #{data.join("\n")}
          }
        DATA
        file = "./app/assets/auto-#{folder}.tmp.scss"
        info.push file
        File.write(file, css)
      end

      Lux.shell.info info.join(' - ')
    end
  end

  # Run every `name.ext.rb` generator under auto/<folder>/{js,css}/.
  # Writes `name.tmp.ext` (gitignored); last expression of the .rb is the body.
  def run_generators! folder, ext
    root = "./app/assets/auto/#{folder}/#{ext}"
    return unless Dir.exist?(root)

    Dir.find(root).select { |f| f.end_with?('.rb') }.each do |rb_path|
      # country_codes.js.rb → country_codes.tmp.js (not country_codes.js)
      base = rb_path.delete_suffix('.rb')
      next unless File.basename(base).include?('.') # skip bare foo.rb

      file_ext = File.extname(base)           # .js / .scss
      stem     = base.delete_suffix(file_ext) # .../country_codes
      out_path = "#{stem}.tmp#{file_ext}"

      body = instance_eval(File.read(rb_path), rb_path).to_s
      File.write(out_path, "#{banner_for(out_path, rb_path)}\n#{body}")

      # drop legacy non-.tmp outputs from older generators
      File.delete(base) if File.exist?(base) && base != out_path

      Lux.shell.info "  gen #{out_path} ← #{rb_path}"
    end
  end

  def banner_for out_path, rb_path
    case File.extname(out_path)
    when '.js', '.coffee', '.fez'
      "// autogenerated from #{rb_path} - do not edit"
    else
      "/* autogenerated from #{rb_path} - do not edit */"
    end
  end

  # Fingerprint public/assets, push each file to the CDN (host app's Cdn
  # class), then write public/manifest.json mapping source name to its
  # fingerprinted filename. Filenames come from CdnAsset.hashed_name so the
  # manifest and runtime CdnAsset.url stay in sync.
  def upload
    cdn_url  = Lux.config.production.cdn_root
    manifest = {}
    failed   = []

    Thread::Simple.each(Dir.files('./public/assets')) do |file|
      target         = CdnAsset.hashed_name(file)
      manifest[file] = target
      local_path     = "./public/assets/#{file}"
      remote_key     = "assets/#{target}"

      ok = Cdn.upload(local_path, target, path: 'assets', dev: false)
      unless ok
        sleep 1 # retry once
        ok = Cdn.upload(local_path, target, path: 'assets', dev: false)
      end

      if ok
        puts "* #{file} -> #{cdn_url}/#{remote_key}"
      else
        failed.push file
        puts "* FAIL #{file} -> #{cdn_url}/#{remote_key}"
      end
    end

    abort "CDN upload failed for: #{failed.join(', ')}" if failed.any?

    File.write('./public/manifest.json', manifest.to_jsonp)
  end

  # Compile production JS/CSS bundles. rollup.config.js cleans public/assets
  # and emits the compiled bundles via the app's bun/rollup toolchain.
  # NODE_PRESERVE_SYMLINKS: rollup.config.js is itself a plugin mount symlink
  # pointing into the gem; without this the resolver follows it to the gem
  # realpath and fails to find rollup-plugin-* in the app's node_modules.
  def build
    system({ 'NODE_PRESERVE_SYMLINKS' => '1' }, 'bun run rollup -c') || abort('asset build failed: bun run rollup -c')
  end

  def get_files(folder, ext)
    root = "./app/assets/auto/#{folder}/#{ext}"
    return [] unless Dir.exist?(root)
    files = Dir.find(root)
    files = files.reject { _1.include?('/!') }
    # generators are materialised to siblings; do not re-eval or list as sources
    files = files.reject { _1.end_with?('.rb') }

    last_file = Dir.files(root).select { _1.include?('!last') }.first
    files.push "#{root}/#{last_file}" if last_file

    files = files.map { _1.sub('./app/assets/', './') }

    files
  end
end

namespace :assets do
  task :auto do
    desc 'Auto assets compiler (app/assets/auto; runs *.ext.rb generators first)'
    # :app so generators can call ViewCell / app constants
    needs :app
    proc do |_opts|
      LuxAssets.auto_assets
    end
  end

  task :build do
    desc 'Compile production JS/CSS bundles (bun run rollup -c)'
    proc do |_opts|
      LuxAssets.build
    end
  end

  task :upload do
    desc 'Fingerprint public/assets, upload to the CDN, regenerate manifest.json'
    # :app (not :env) so the host app's Cdn class is autoloaded for the upload.
    needs :app
    proc do |_opts|
      LuxAssets.upload
    end
  end

  task :deploy do
    desc 'Full asset pipeline: auto -> build -> upload'
    # :app so the upload step can reach the host app's Cdn class.
    needs :app
    proc do |_opts|
      hammer 'assets:auto'
      hammer 'assets:build'
      hammer 'assets:upload'
    end
  end
end
